const body = $json.body ?? $json;
const solicitud = typeof body.solicitud === 'string' ? body.solicitud.trim() : '';
if (!solicitud || solicitud.length > 2000) {
  const error = !solicitud ? 'El campo solicitud es obligatorio.' : 'La solicitud no puede superar los 2000 caracteres.';
  return [{ json: { valid: false, error, ok: false, data: null } }];
}
let apiBaseUrl;
try {
  const parsed = new URL(typeof body.apiBaseUrl === 'string' ? body.apiBaseUrl.trim() : '');
  if (!['http:', 'https:'].includes(parsed.protocol) || parsed.username || parsed.password || parsed.pathname !== '/' || parsed.search || parsed.hash) {
    throw new Error('URL no permitida');
  }
  apiBaseUrl = parsed.origin;
} catch {
  return [{ json: { valid: false, error: 'El backend no envió un origen de API válido.', ok: false, data: null } }];
}
return [{ json: { valid: true, solicitud, apiBaseUrl } }];

let raw = $json.output ?? $json.text ?? $json.response ?? '';
if (typeof raw !== 'string') raw = JSON.stringify(raw);
raw = raw.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/, '');
let data;
try { data = JSON.parse(raw); } catch {
  return [{ json: { ok: false, data: null, error: 'El agente no devolvió JSON válido. Revisa la ejecución del workflow.' } }];
}
if (!data || typeof data !== 'object' || !Array.isArray(data.sugerencias) || typeof data.resumen !== 'string') {
  return [{ json: { ok: false, data: null, error: 'La salida del agente no cumple el esquema resumen/sugerencias.' } }];
}
return [{ json: { ok: true, data, error: null } }];
